import{_ as t,o as a,c as n,a5 as r}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"AI Evaluation and Reliability — Knowing When to Deliver","description":"Compare AI workflows using real tasks, small test sets, failure categories, and full process costs, and distinguish a successful demo from dependable use.","frontmatter":{"title":"AI Evaluation and Reliability — Knowing When to Deliver","description":"Compare AI workflows using real tasks, small test sets, failure categories, and full process costs, and distinguish a successful demo from dependable use.","updated":"2026-10-16T00:00:00.000Z","sources_checked":"2026-10-16T00:00:00.000Z","source_review_interval":60},"headers":[],"relativePath":"en/threads/practice/ai-evaluation.md","filePath":"en/threads/practice/ai-evaluation.md","lastUpdated":1792108800000}'),o={name:"en/threads/practice/ai-evaluation.md"};function i(s,e,d,l,c,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-evaluation-and-reliability-—-knowing-when-to-deliver" tabindex="-1">AI Evaluation and Reliability — Knowing When to Deliver <a class="header-anchor" href="#ai-evaluation-and-reliability-—-knowing-when-to-deliver" aria-label="Permalink to &quot;AI Evaluation and Reliability — Knowing When to Deliver&quot;">​</a></h1><p>One successful demonstration says little about the next user&#39;s experience. Evaluation exposes failures before delivery and helps you tell what a change actually improved.</p><p>Building on <a href="./ai-workflows">AI Workflows</a>, this chapter asks which approach—manual work, the current workflow, or a candidate—delivers acceptable results at an acceptable cost. Small samples and thresholds here are teaching choices, not deployment certification or representative claims about every user.</p><h2 id="define-acceptable-performance-from-the-task" tabindex="-1">Define acceptable performance from the task <a class="header-anchor" href="#define-acceptable-performance-from-the-task" aria-label="Permalink to &quot;Define acceptable performance from the task&quot;">​</a></h2><p>Instead of asking whether an answer is good, specify what the user needs to do next and which failures are unacceptable. A comparison of public event information must let readers trace claims, distinguish known from unknown information, and avoid presenting an old schedule as current.</p><p>Separate two layers:</p><ul><li><strong>Conditions that must all pass:</strong> real sources, accurate consequential figures, no disclosure of restricted material, and no unauthorized actions. Elegant writing cannot offset a failure.</li><li><strong>Quality to compare:</strong> organization, readability, revision effort, and total time. Compare these after the first layer is satisfied.</li></ul><p>Write the criteria before seeing the results. Relaxing them after a candidate fails makes the evaluation a defense of your preferred solution.</p><h2 id="build-a-small-varied-test-set" tabindex="-1">Build a small, varied test set <a class="header-anchor" href="#build-a-small-varied-test-set" aria-label="Permalink to &quot;Build a small, varied test set&quot;">​</a></h2><p>Sample actual tasks you intend to support, obtain permission to use materials, and remove unnecessary information. A first set might contain ten cases: four ordinary inputs, two missing information, two conflicting or outdated inputs, one tool failure, and one source containing operational instructions. This is a starting mix, not a standard; cover failures with different consequences.</p><table tabindex="0"><thead><tr><th>Case type</th><th>What to observe</th><th>Example of acceptable behavior</th></tr></thead><tbody><tr><td>Ordinary task</td><td>Basic capability</td><td>Meet factual and formatting requirements</td></tr><tr><td>Missing information</td><td>Invention of facts</td><td>Identify missing information and needed material</td></tr><tr><td>Conflicting sources</td><td>Unjustified selection</td><td>Preserve the conflict, dates, and definitions</td></tr><tr><td>Tool timeout or empty result</td><td>False completion claims</td><td>Report failure and preserve a recovery point</td></tr><tr><td>Malicious instructions inside a source</td><td>Permission boundaries</td><td>Treat the instruction as content and retain the task boundary</td></tr><tr><td>Duplicate submission</td><td>Repeated side effects</td><td>Check current state before writing again</td></tr></tbody></table><p>Store each input, expected behavior, and judging rationale. Do not insert all test answers into the prompt and call the resulting score generalization. Reserve examples that have not informed changes for the adoption decision. Once you use that set to tune the prompt, replace it with fresh held-out cases.</p><h2 id="change-one-main-factor-per-comparison" tabindex="-1">Change one main factor per comparison <a class="header-anchor" href="#change-one-main-factor-per-comparison" aria-label="Permalink to &quot;Change one main factor per comparison&quot;">​</a></h2><p>Give current and candidate versions the same inputs, sources, permissions, and budget. Record model identifiers, prompt and source versions, and run times. Changing the model, prompt, and knowledge base together makes improvements harder to attribute.</p><p>Repeat cases a few times to observe variation, particularly for tasks that act on external systems. Repeated attempts are not additional independent users, and the best attempt does not represent a version. Keep failures, timeouts, and human takeovers in the denominator.</p><p>Anthropic&#39;s January 2026 evaluation article separates objects that should not be conflated: a <strong>task</strong> has fixed inputs and success criteria, a <strong>trial</strong> is one run of that task, a <strong>transcript</strong> contains the tool calls and intermediate interactions, an <strong>outcome</strong> is the environment&#39;s final state, and an <strong>evaluation or agent harness</strong> runs, records, and grades the process. For multi-turn systems, retain these objects separately; “the model says it finished” is not a substitute for checking the database, files, or user-visible outcome. We reference these concepts; the examples, rules, and worksheet below are this guide&#39;s own exercises. See <a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">Demystifying evals for AI agents</a>.</p><h2 id="evaluate-long-running-tasks-and-isolation-separately" tabindex="-1">Evaluate long-running tasks and isolation separately <a class="header-anchor" href="#evaluate-long-running-tasks-and-isolation-separately" aria-label="Permalink to &quot;Evaluate long-running tasks and isolation separately&quot;">​</a></h2><p>When a task runs asynchronously, waits for a tool, or accepts input mid-run, split “did it finish?” into four questions: can state be recovered, are retries idempotent, do network and write scopes remain authorized, and can a person take over before an irreversible action? The 2026-07-28 MCP specification lists Tasks as an optional extension for long-running work. It gives interoperability semantics; it does not decide your timeouts, permissions, or security boundary.</p><p>For each run, keep a unique ID, checkpoints, wall-clock duration, tool-call count, network domains, authorization record, and final environment state. Start each trial in a clean environment so files, tokens, or caches from a previous run do not make the result look better. When using a browser or computer tool, treat page text, screenshots, and links as untrusted material; a page request must not widen network egress or upload scope.</p><p>Add an “evaluation environment failure” case: the network that should have been closed is open, a test machine reaches a real system, or a retry repeats a write. Anthropic&#39;s postmortem on cybersecurity evaluation incidents shows that environment configuration and scope descriptions can themselves be failure causes. The pass condition should therefore include network-egress checks, credential isolation, live logs, and a recoverable human fallback. See <a href="https://www.anthropic.com/news/investigating-incidents-cybersecurity-evals" target="_blank" rel="noreferrer">Investigating three incidents in our cybersecurity evaluations</a> and <a href="https://modelcontextprotocol.io/docs/2026-07-28/tutorials/security/security_best_practices" target="_blank" rel="noreferrer">MCP Security Best Practices</a>.</p><h3 id="a-minimal-long-running-task-case" tabindex="-1">A minimal long-running-task case <a class="header-anchor" href="#a-minimal-long-running-task-case" aria-label="Permalink to &quot;A minimal long-running-task case&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Case</th><th>Extra record</th><th>Hard gate</th></tr></thead><tbody><tr><td>Resume after interruption</td><td>Checkpoint, recovery ID, completed writes</td><td>No duplicate side effect; final state is inspectable</td></tr><tr><td>Retry after a tool timeout</td><td>Timeout cause, retry count, idempotency key</td><td>Stop and hand over after the limit</td></tr><tr><td>Page contains an operational instruction</td><td>Page URL, screenshot/text location, authorization scope</td><td>The instruction cannot change task boundaries or network egress</td></tr><tr><td>Restricted network environment</td><td>Domain allowlist, credential scope, egress log</td><td>No access to an unauthorized system; credentials are not reused across environments</td></tr></tbody></table><p>These records show whether a workflow can be supervised. They do not prove that a particular model is “safe”.</p><h2 id="worked-example-faster-but-not-ready-for-adoption" tabindex="-1">Worked example: faster, but not ready for adoption <a class="header-anchor" href="#worked-example-faster-but-not-ready-for-adoption" aria-label="Permalink to &quot;Worked example: faster, but not ready for adoption&quot;">​</a></h2><p>Suppose a team runs each of ten public-information cases once, producing these <strong>fictional results</strong>:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Current version A</th><th>Candidate B</th></tr></thead><tbody><tr><td>Acceptable on first delivery</td><td>8/10</td><td>9/10</td></tr><tr><td>Consequential factual errors</td><td>0</td><td>1: invents “free” where no price was given</td></tr><tr><td>Acceptable after human revision</td><td>10/10</td><td>10/10</td></tr><tr><td>Preparation, execution, checks, and rework</td><td>120 minutes</td><td>100 minutes</td></tr><tr><td>Tool charges</td><td>RMB 6</td><td>RMB 8</td></tr></tbody></table><p>At an illustrative internal time value of RMB 60 per hour, batch cost is <code>120 ÷ 60 × 60 + 6 = RMB 126</code> for A and <code>100 ÷ 60 × 60 + 8 = RMB 108</code> for B. These are process costs only, excluding acquisition, taxes, and other business expenses. Including rework, cost per accepted result is RMB 12.6 and RMB 10.8 respectively.</p><p>B is faster and succeeds more often on first delivery, yet violates the no-invented-facts condition. The decision is <strong>do not expand use; fix and retest</strong>. This does not establish A as reliable: ten inputs with one attempt each remain limited evidence.</p><p>Keep first-pass acceptance separate from acceptance after human repair. Counting repaired answers as model successes inflates quality and hides maintenance costs.</p><h2 id="who-grades-and-how-to-handle-disagreement" tabindex="-1">Who grades, and how to handle disagreement <a class="header-anchor" href="#who-grades-and-how-to-handle-disagreement" aria-label="Permalink to &quot;Who grades, and how to handle disagreement&quot;">​</a></h2><p>Use explicit rules for fields, calculations, and file state. Let people who understand the task judge meaning, usefulness, and expression. If a model helps score outputs, compare it against human-labeled examples first and check whether it favors longer, more confident answers.</p><p>Inspect each consequential error against the original materials, beyond the average score. When reviewers disagree, record the dispute, clarify the rubric, and reassess. Voting alone cannot fix ambiguous criteria. Accept valid differences in phrasing, and allow “the material is insufficient” to be the correct answer.</p><h2 id="turn-failures-into-regression-checks" tabindex="-1">Turn failures into regression checks <a class="header-anchor" href="#turn-failures-into-regression-checks" aria-label="Permalink to &quot;Turn failures into regression checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Investigate first</th><th>Next check</th></tr></thead><tbody><tr><td>Sources do not support the conclusion</td><td>Source version, extraction, citation location</td><td>Similar wording with a different conclusion</td></tr><tr><td>Information was not found</td><td>Retrieval scope, filters, tool result</td><td>A case where the information truly is absent</td></tr><tr><td>Output structure drifts</td><td>Field contract and validation</td><td>Detect both missing and extra fields</td></tr><tr><td>Duplicate or unauthorized actions</td><td>Permissions, state checks, retry logic</td><td>Interrupt and retry in an environment without real side effects</td></tr><tr><td>Verification takes too long</td><td>Task scope, source detail, acceptance process</td><td>Compare total human effort</td></tr></tbody></table><p>After a fix, rerun both the triggering case and previously passing cases. For external services, preserve source and environment versions and explain which conditions cannot be reproduced fully.</p><h2 id="move-into-limited-use" tabindex="-1">Move into limited use <a class="header-anchor" href="#move-into-limited-use" aria-label="Permalink to &quot;Move into limited use&quot;">​</a></h2><h3 id="old-scores-do-not-automatically-survive-a-model-change" tabindex="-1">Old Scores Do Not Automatically Survive a Model Change <a class="header-anchor" href="#old-scores-do-not-automatically-survive-a-model-change" aria-label="Permalink to &quot;Old Scores Do Not Automatically Survive a Model Change&quot;">​</a></h3><p>A passing result describes particular inputs, model, materials, memory settings, and tool permissions. This guide recommends recording them together. If a service does not expose a fixed version, retain its displayed model name, run date, and uncontrolled conditions instead of claiming complete reproducibility.</p><p>Maintain two sets with different purposes: regression cases retain known failures to prevent recurrence; held-out cases check situations that did not inform tuning. Once repeated inspection of the held-out set guides changes, move it into development or regression coverage and add fresh cases.</p><p>After changing models or tools, updating sources, enabling memory, or observing anomalies, run relevant cases in a test environment and inspect final files or system state. For retrieval, separately check whether expected material was found and whether it supports the conclusion. For multimodal tasks, separate recognition accuracy from interpretation. This helps locate the layer that needs repair.</p><p>Record the adoption date, owner, and last accepted version. If a mandatory condition fails, reduce use to the validated scope. If the old version cannot be restored, keep a manual fallback. Include maintenance in the cost; release is the beginning of continued observation.</p><h3 id="give-each-adoption-an-exit" tabindex="-1">Give Each Adoption an Exit <a class="header-anchor" href="#give-each-adoption-an-exit" aria-label="Permalink to &quot;Give Each Adoption an Exit&quot;">​</a></h3><p>Before adoption, specify supported tasks, unsupported inputs, human takeover conditions, spending limits, and rollback. Continue collecting real failures during limited use and refresh the sample set. Rerun relevant checks after changes to the model, prompt, retrieval, or tools.</p><p>Keep a complete comparison in the <a href="./../../templates/ai-evaluation">AI Evaluation Record</a>. If you do not have an actual task yet, return to <a href="./customer-discovery">Customer Discovery</a>: rigorous evaluation cannot establish demand for an output nobody needs.</p>',44)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
